    Lemma spf : alloc_ceiling + STK <= sp /\ sp < 2 ^ 47 /\ sp mod 16 = 0 /\ 0x7fff7f800000 <= alloc_ceiling <= 0x7fffff800000 /\ 2 ^ 24 <= sp - STK /\
