    Lemma knowU : forall A1 M1 model1 b1 cap1 ys Rk (t0 : Z),
      PINV A1 M1 model1 b1 cap1 ys -> TFR M1 -> 1 <= Zlen ys ->
      let E := Eseed Rk [Z_to_bv 64 sp; Z_to_bv 64 pat; getr R 1%bv; getr R 8%bv; getr R 9%bv; getr R 18%bv; Z_to_bv 64 t0;
                          Z_to_bv 64 (b1 + 4 * Zlen ys); Z_to_bv 64 (b1 + 4 * cap1)] in
      know_ok SEGS E M1 [KWr (SA (EVar 32) (-64)) (ELit 64);
                         KWord (SA (EVar 32) (-8)) (N.to_nat 8) (EVar 34); KWord (SA (EVar 32) (-16)) (N.to_nat 8) (EVar 35);
                         KWord (SA (EVar 32) (-24)) (N.to_nat 8) (EVar 36); KWord (SA (EVar 32) (-32)) (N.to_nat 8) (EVar 37);
                         KWord (SA (EVar 32) (-40)) (N.to_nat 8) (ELit TU_BACK); KWord (SA (EVar 32) (-48)) (N.to_nat 8) (EVar 33);
                         KRange (EVar 33) 1 (2 ^ 63); KAlign (EVar 33) 8; KWr (SA (EVar 33) 0) (ELit 24);
                         KDisj (SA (EVar 33) 0) (ELit 24) (SA (EVar 32) (-64)) (ELit 64);
                         KWord (SA (EVar 33) 8) (N.to_nat 8) (EVar 39); KWord (SA (EVar 33) 16) (N.to_nat 8) (EVar 40);
                         KRange (EVar 39) 16 (2 ^ 47); KAlign (EVar 39) 4; KRange (EVar 40) 16 (2 ^ 47)]
      /\ (1 <= Zlen ys -> know_ok SEGS E M1 [KDisj (SA (EVar 39) (-4)) (ELit 4) (SA (EVar 32) (-64)) (ELit 64);
                                             KDisj (SA (EVar 39) (-4)) (ELit 4) (SA (EVar 33) 0) (ELit 24)])
      /\ (forall nf, 0 < nf -> Zlen ys + nf <= cap1 -> know_ok SEGS E M1 [KWr (SA (EVar 39) 0) (ELit (4 * nf)); KDisj (SA (EVar 39) 0) (ELit (4 * nf)) (SA (EVar 32) (-64)) (ELit 64);
                                              KDisj (SA (EVar 39) 0) (ELit (4 * nf)) (SA (EVar 33) 0) (ELit 24)])
      /\ (forall tl zs, ys = zs ++ [tl] -> 0 <= tl < 2 ^ 32 -> know_ok SEGS E M1 [KWord (SA (EVar 39) (-4)) (N.to_nat 4) (ELit tl)])
      /\ 16 <= b1 /\ b1 + 4 * cap1 <= alloc_ceiling /\ 0 <= Zlen ys <= cap1 /\ b1 mod 16 = 0.
