      edenot (Eseed R [Z_to_bv 64 sp; Z_to_bv 64 pat; Z_to_bv 64 t; Z_to_bv 64 (b + 4 * Zlen xs); Z_to_bv 64 (b + 4 * cap)]) te = Z_to_bv 64 t ->
      let E := Eseed R [Z_to_bv 64 sp; Z_to_bv 64 pat; Z_to_bv 64 t; Z_to_bv 64 (b + 4 * Zlen xs); Z_to_bv 64 (b + 4 * cap)] in
      know_ok SEGS E M ([KWr (SA (EVar 32) (-64)) (ELit 64);
                         KRange (EVar 33) 1 (2 ^ 63); KAlign (EVar 33) 8; KWr (SA (EVar 33) 0) (ELit 24);
                         KDisj (SA (EVar 33) 0) (ELit 24) (SA (EVar 32) (-64)) (ELit 64);
                         KWord (SA (EVar 33) 8) (N.to_nat 8) (EVar 35); KWord (SA (EVar 33) 16) (N.to_nat 8) (EVar 36);
                         KRange (EVar 35) 20 (2 ^ 47); KAlign (EVar 35) 4; KRange (EVar 36) 16 (2 ^ 47);
                         KWord (SA (EVar 35) (-4)) (N.to_nat 4) te;
                         KDisj (SA (EVar 35) (-4)) (ELit 4) (SA (EVar 32) (-64)) (ELit 64);
                         KDisj (SA (EVar 35) (-4)) (ELit 4) (SA (EVar 33) 0) (ELit 24)]
                        ++ (if 0 <? nf then [KWr (SA (EVar 35) (-4)) (ELit (4 * nf));
                                             KDisj (SA (EVar 35) (-4)) (ELit (4 * nf)) (SA (EVar 32) (-64)) (ELit 64);
                                             KDisj (SA (EVar 35) (-4)) (ELit (4 * nf)) (SA (EVar 33) 0) (ELit 24)] else []))
      /\ regs_ok E (srs sr_id [(2%bv, EVar 32); (10%bv, EVar 33)]) R
      /\ 16 <= b /\ b + 4 * cap <= alloc_ceiling /\ 1 <= Zlen xs <= cap /\ b mod 16 = 0 /\ 0 <= t < 2 ^ 31.
