    Lemma CALLU : forall (first : bool) A1 M1 model1 b1 cap1 ys R1 (ra src x t0 : Z),
      PINV A1 M1 model1 b1 cap1 ys -> TFR M1 -> SAME R1 ->
      Zlen xs - 1 <= Zlen ys -> Zlen ys < Zlen xs - 1 + 3 -> Zlen ys = cap1 ->
      getr R1 10%bv = Z_to_bv 64 pat -> getr R1 11%bv = Z_to_bv 64 src -> getr R1 2%bv = Z_to_bv 64 (sp - 64) ->
      getr R1 1%bv = Z_to_bv 64 ra -> ret_ok (Z_to_bv 64 ra) -> 0 <= ra < 2 ^ 64 ->
      getr R1 8%bv = Z_to_bv 64 pat -> getr R1 9%bv = Z_to_bv 64 t0 -> getr R1 18%bv = Z_to_bv 64 5 ->
      (src = sp - 52 \/ src = sp - 56) -> fld SEGS M1 src 4 x -> 0 <= x < 2 ^ 31 ->
      (forall A' R' M' model' (b' cap' : Z),
         PINV A' M' model' b' cap' (ys ++ [x]) -> TFR M' -> SAME R' ->
         getr R' 2%bv = Z_to_bv 64 (sp - 64) -> getr R' 8%bv = Z_to_bv 64 pat -> getr R' 9%bv = Z_to_bv 64 t0 -> getr R' 18%bv = Z_to_bv 64 5 ->
         getr R' 10%bv = Z_to_bv 64 (b' + 4 * (Zlen ys + 1)) ->
         srealizes SEGS (mkCfg (@mkst fx R' (Z_to_bv 64 ra) M' (seg_rom SEGS)) model') K) ->
      srealizes SEGS (mkCfg (@mkst fx R1 (Z_to_bv 64 (if first then PBS_ENTRY else PBS2_ENTRY)) M1 (seg_rom SEGS)) model1) K.
