    Ltac sc_bra := cbn [sc_denot]; evs; rewrite ?zbv_add; zl; rewrite ?br_eq, ?br_ne, ?br_ltu, ?br_geu by lia; bool_lia.

    Ltac segU PIk TFk G2 G8 G9 G18 G10 nf ds :=
      lazymatch type of PIk with TablPush.PINV _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?A1 ?M1 ?model1 ?b1 ?cap1 ?ys =>
      lazymatch type of G9 with getr ?Rk _ = Z_to_bv 64 ?t0 =>
        let HK0 := fresh "HK0" in let HKnf := fresh "HKnf" in let HK := fresh "HK" in let HR := fresh "HR" in
        let Hb := fresh "Hb16_" in let Hce := fresh "Hce_" in let Hl := fresh "Hlen_" in let Hal := fresh "Hal_" in
        let MSk := fresh "MS_" in
        pose proof (pinv_mstd _ _ _ _ _ _ PIk) as MSk;
        destruct (knowU A1 M1 model1 b1 cap1 ys Rk t0 PIk TFk ltac:(zl; unfold Zlen in *; lia)) as (HK0 & _ & HKnf & _ & Hb & Hce & Hl & Hal);
        cbv zeta in HK0; rewrite ?Zlen_app1, ?(Zlen_removelast xs Hne) in Hl;
        lazymatch nf with
        | 0 => pose proof HK0 as HK
        | _ => pose proof (proj2 (Forall_app _ _ _) (conj HK0 (HKnf nf ltac:(lia) ltac:(zl; unfold Zlen in *; lia)))) as HK; cbn [app] in HK; know_fix HK
        end;
        clear HK0 HKnf;
        pose proof (regsU Rk t0 (-64) b1 ys cap1 true ltac:(rewrite G2; f_equal; lia) G8 G9 G18 ltac:(intros _; rewrite G10; f_equal; zl; lia)) as HR; cbn [app] in HR;
        xruns HR HK 80%nat TU_STOPS (SCR ds [] []) 41%N; [split_scs; first [sc_fl | sc_br | sc_bra] |];
        clear HK HR; norm_mem
      end end.

    Ltac tfr_of TFk := idtac;
      let C1 := fresh "C" in let C2 := fresh "C" in let C3 := fresh "C" in let C4 := fresh "C" in let C5 := fresh "C" in let C6 := fresh "C" in
      pose proof TFk as (C1 & C2 & C3 & C4 & C5 & C6); tfr_tower C1 C2 C3 C4 C5 C6.

    Ltac lastU tfk SMk TFv :=
      lazymatch goal with HR' : regs_ok _ _ ?Rn |- srealizes _ (mkCfg (@mkst _ ?Rn _ ?T _) ?mo) _ =>
        eapply (LASTSEG _ T mo _ _ Rn);
        [ pinv_build T ltac:(fun H => exact H)
        | tfk
        | same_of HR' SMk
        | regfrom HR' | regfrom HR' | regfrom HR' | regfrom HR'
        | inl
        | rewrite TFv; cbn [snd]; rewrite <- ?app_assoc; reflexivity
        | rewrite TFv; reflexivity ]
      end.

    Ltac callU tfk SMk x :=
      lazymatch goal with HR' : regs_ok _ _ ?Rn |- srealizes _ (mkCfg (@mkst _ ?Rn _ ?T _) ?mo) _ =>
        eapply (CALLU false _ T mo _ _ _ Rn _ (sp - 56) x);
        [ pinv_build T ltac:(fun H => exact H)
        | tfk
        | same_of HR' SMk
        | zl; unfold Zlen in *; lia | zl; unfold Zlen in *; lia | zl; unfold Zlen in *; lia
        | regfrom HR' | regfrom HR' | regfrom HR' | regfrom HR' | apply bv_eq; vm_compute; reflexivity | lia
        | regfrom HR' | regfrom HR' | regfrom HR'
        | right; reflexivity | apply fld_wbytes4; lia | lia
        | clear HR' ]
      end.

    Lemma MAIN : srealizes SEGS (mkCfg (@mkst fx R (Z_to_bv 64 TU_ENTRY) M (seg_rom SEGS)) model) K.
Proof using AC MI ST cpbs1 cpbs2 MSpos Hcp1 Hcp2 PBS1 PBS2 fx A s R M model sp ret pat b cap xs K CB Ha0 VEC Hne OBJ PAT8 Hx31 NMX RP CONT.
Ltac entryU tv te nf ds Et :=
        let HK := fresh "HK" in let HR := fresh "HR" in
        destruct (knowE tv te nf Et ltac:(lia) ltac:(lia) ltac:(evs; reflexivity)) as (HK & HR & ? & _ & _ & ? & _); cbv zeta in HK;
        first [change (0 <? nf) with true in HK | change (0 <? nf) with false in HK]; cbn [app] in HK;
        xruns HR HK 120%nat TU_STOPS (SCR ds [] []) 37%N;
        [ split_scs; first [sc_fl | sc_br | sc_bra
                           | cbn [sc_denot]; evs; rewrite ?(ext_val_sx_id 4) by (first [lia | rewrite u64_of_Z by lia; cbn; lia]);
                             rewrite ?br_ge, ?br_lt, ?br_eq, ?br_ne by lia; bool_lia ] |];
        clear HK; norm_mem.
